import{useEffect,useRef}from'react';
export function roveIndex(key,current,count,opts={}){
if(count<=0)
return null;
const{orientation='vertical',loop=true}=opts;
const prev=(orientation==='vertical'&&key==='ArrowUp')||(orientation==='horizontal'&&key==='ArrowLeft')||(orientation==='both'&&(key==='ArrowUp'||key==='ArrowLeft'));
const next=(orientation==='vertical'&&key==='ArrowDown')||(orientation==='horizontal'&&key==='ArrowRight')||(orientation==='both'&&(key==='ArrowDown'||key==='ArrowRight'));
if(key==='Home')
return 0;
if(key==='End')
return count-1;
if(!prev&&!next)
return null;
if(current<0)
return prev?count-1:0;
const to=current+(next?1:-1);
if(to<0)
return loop?count-1:0;
if(to>=count)
return loop?0:count-1;
return to;
}
export function enabledIn(container,selector){
if(!container)
return[];
return[...container.querySelectorAll(selector)].filter((el)=>!el.hasAttribute('disabled')&&el.getAttribute('aria-disabled')!=='true');
}
export function roveFocus(event,container,selector,opts){
const items=enabledIn(container,selector);
const active=typeof document==='undefined'?null:document.activeElement;
const to=roveIndex(event.key,active?items.findIndex((el)=>el===active||el.contains(active)):-1,items.length,opts);
if(to===null)
return false;
event.preventDefault();
items[to]?.focus();
if(opts?.activate)
items[to]?.click();
return true;
}
export function useDismiss(open,onDismiss,inside,opts={}){
const latest=useRef({onDismiss,inside});
latest.current={onDismiss,inside};
const{escape=true,outside=true}=opts;
useEffect(()=>{
if(!open)
return;
const onKey=(e)=>{
if(e.key==='Escape'&&!e.defaultPrevented)
latest.current.onDismiss('escape');
};
const onPress=(e)=>{
const target=e.target;
if(!target)
return;
if(latest.current.inside.some((ref)=>ref.current?.contains(target)))
return;
latest.current.onDismiss('outside');
};
if(escape)
document.addEventListener('keydown',onKey);
if(outside)
document.addEventListener('pointerdown',onPress);
return()=>{
document.removeEventListener('keydown',onKey);
document.removeEventListener('pointerdown',onPress);
};
},[open,escape,outside]);
}
